    /// <summary>
    /// Method to reset map and the mark on grid
    /// </summary>
    /// <param name = "_map">Map reference</param>
    public void cleanupMarkMap(Map      _map)
    {
        Set             setRec = new Set(Types::Int64);
        MapEnumerator   mapEnumerator = _map.getEnumerator();
        SetEnumerator   setEnumerator;

        while (mapEnumerator.moveNext())
        {
            setRec.add(mapEnumerator.currentKey());
        }

        setEnumerator = setRec.getEnumerator();

        while (setEnumerator.moveNext())
        {
            if (_map.exists(setEnumerator.current()))
            {
                _map.remove(setEnumerator.current());
            }
        }

        SalesTable_ds.executeQuery();
    }

    /// <summary>
    /// Enable or disable buttons based on records selection
    /// </summary>
    public void enableOrDisableButtons()
    {
        boolean hasSelection        = !paMarked.empty();
        boolean isExtracted         = metOrderExtractScreenParameters.parmExtracted() == METOrderExtractStatus::Extracted;
        boolean checkPicklist       = this.checkMarkedOrdersPicklist();

        boolean anyProcessing = false;
        if (hasSelection)
        {
            SalesTable salesTableLoc;
            MapEnumerator mapEnum = paMarked.getEnumerator();
            while (mapEnum.moveNext())
            {
                select firstonly METProcessing from salesTableLoc
                    where salesTableLoc.RecId == mapEnum.currentKey();
                if (salesTableLoc.METProcessing == NoYes::Yes)
                {
                    anyProcessing = true;
                    break;
                }
            }
        }

        // Enable or disable controls based on selection status
        METOrderExtractScreenModifyDialog.enabled(hasSelection && checkPicklist);
        Calculate.enabled(hasSelection);

        UpdateStatusFormButtonControl.enabled(hasSelection);
        METSalesPickingListGeneration.enabled(hasSelection && !isExtracted && !anyProcessing);        
    }

    /// <summary>
    /// Returns true when none of the marked orders have an associated picklist.
    /// If any marked order has a picklist number (i.e. a WMS picking route/line exists for the SalesId),
    /// this returns false.
    /// </summary>
    /// <returns>true if none of the marked orders have a picklist; otherwise, false.</returns>
    private boolean checkMarkedOrdersPicklist()
    {
        str             salesId;
        str             picklistNumber;
        SalesTable      salesTableLoc;
        MapEnumerator   mapEnumerator = paMarked.getEnumerator();

        if (paMarked.empty())
        {
            return false;
        }

        while (mapEnumerator.moveNext())
        {
            salesId = mapEnumerator.currentValue();

            picklistNumber = SalesTable::getLastPickListInfo(salesId).pickingRouteID;

            if (picklistNumber)
            {
                salesTableLoc = SalesTable::find(salesId);

                if (salesTableLoc.METOrderExtractStatus == METOrderExtractStatus::Open && salesTableLoc.METAllowBackOrders)
                {
                    continue;
                }
                else
                {
                    return false;
                }
            }
        }

        // No picklists found for any marked orders -> UpdateStatus can be enabled
        return true;
    }

