/// <summary>
/// Return wavid for the sales order
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
/// <returns>Wave Id</returns>
[SysClientCacheDataMethodAttribute(true)]
display METWaveId displayWaveId(SalesTable _salesTable)
{
    return METWaveLine::findByDocumentNumber(_salesTable.SalesId).WaveId;
}

        /// <summary>
        /// Return wavid for the sales order
        /// </summary>
        /// <param name = "_salesTable">Sales order header</param>
        /// <returns>Wave status</returns>
        [SysClientCacheDataMethodAttribute(true)]
        display str displayWaveStatus(SalesTable _salesTable)
        {
            METWaveTable waveTable;
            METWaveLine  waveLine;

            select firstonly WaveId from waveLine
                where waveLine.DocumentNumber == _salesTable.SalesId
                join WaveStatus from waveTable
                    where waveTable.WaveId == waveLine.WaveId;
            
            return enum2Symbol(enumNum(METCSDWaveStatus), enum2int(waveTable.WaveStatus));
        }

        /// <summary>
        /// This is an edit method
        /// </summary>
        /// <param name = "_set">Set</param>
        /// <param name = "_salesTable">SalesTable</param>
        /// <param name = "_markTrans">MarkTrans</param>
        /// <returns>EditValue</returns>
        [SysClientCacheDataMethodAttribute(true)]
        public edit NoYes editMarkTrans(boolean _set, SalesTable _salesTable, NoYes _markTrans)
        {
           
            if (_set)
            {
                if(!_markTrans)
                {
                    if(paMarked.exists(_salesTable.RecId))
                    {
                        paMarked.remove(_salesTable.RecId);
                    }
                }
                else
                {
                    _salesTable.reread();

                    // To validate any sales order selected which is already Extracted throw an error
                    if (_salesTable.METOrderExtractStatus == METOrderExtractStatus::Extracted)
                    {   
                        error(strFmt("@MET:METSalesOrderAlreadyExtracted", _salesTable.SalesId));
                    }
                    else if (_salesTable.METProcessing == NoYes::Yes)
                    {
                        warning(strFmt("@MET:METOrderExtractingWarning", _salesTable.SalesId));
                        paMarked.insert(_salesTable.RecId, _salesTable.SalesId);
                    }
                    else
                    {
                        paMarked.insert(_salesTable.RecId, _salesTable.SalesId);
                    }

                }
                //Bug 229712 CB628 - Update status in extraction screen got refresh issue -start
                element.enableOrDisableButtons();
                //Bug 229712 CB628 - Update status in extraction screen got refresh issue -end
            }
            return paMarked.exists(_salesTable.RecId);
        }

